@js:
var s = [];

function p(t, u, f, b) {
    s.push({
        title: t,
        url: u || '',
        style: {
            layout_flexGrow: f,
            layout_flexBasisPercent: b
        }
    });
}


s.push({
    title: "☃关键词💭：书名/作者",
    type: "text",
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: 0.6
    }
});
s.push({
    title: "🔍搜索",
    type: "button",
    action: "java.searchBook(infoMap['☃关键词💭：书名/作者'] || '', `${source.bookSourceName}::${source.getKey()}`);saveKeys(infoMap)",
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: -1,
        layout_alignSelf: "baseline"
    }
});
s.push({
    title: "⚙登录",
    type: "button",
    action: "java.open('login','http',null);saveKeys(infoMap)",
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: 0.4,
        layout_alignSelf: "baseline"
    }
});
s.push({
    title: "🔄刷新发现页",
    type: "button",
    action: "java.refreshExplore()",
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: 0.4,
        layout_alignSelf: "baseline"
    }
});


var config = {};
try {
    var raw = source.getVariable();
    if (raw && raw !== '' && raw !== 'null' && raw !== 'undefined') {
        config = JSON.parse(raw);
    }
} catch (e) {}

var selectedGroup = config.exploreGroup || '排行榜';


s.push({
    title: "📁 选择分组",
    type: "select",
    chars: ["📊 排行榜", "📚 分类", "🏷️ 标签"],
    default: (function() {
        var map = {
            '排行榜': '📊 排行榜',
            '分类': '📚 分类',
            '标签': '🏷️ 标签'
        };
        return map[selectedGroup] || '📊 排行榜';
    })(),
    action: "(function(){ try { var c = {}; try { c = JSON.parse(source.getVariable() || '{}'); } catch(e) { c = {}; } var raw = infoMap['📁 选择分组'] || '📊 排行榜'; var map = {'📊 排行榜':'排行榜','📚 分类':'分类','🏷️ 标签':'标签'}; c.exploreGroup = map[raw] || '排行榜'; source.setVariable(JSON.stringify(c)); java.refreshExplore(); } catch(e){ java.toast('切换失败：'+e); } })()",
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: 1
    }
});


function addRank(rankList) {
    rankList.forEach(function(r) {
        [1, 2].forEach(function(t) {
            p(
                (t == 1 ? '男频' : '女频') + r[0],
                '/leader-board?rank_type=' + r[1] + '&category_id=0&tab_type=' + t +
                '&category_type=0&imei_ip=2937357107&book_privacy=1&read_preference=0',
                1, 0.4
            );
        });
    });
}

if (selectedGroup === '排行榜') {
    addRank([
        ['推荐榜⭐', 'rec_list'],
        ['必读榜📖', 'must_read_list'],
        ['大热榜🔥', 'hot_list'],
        ['匠心榜✨', 'craft_list'],
        ['完结榜🎬', 'end_list'],
        ['新书榜🆕', 'new_list'],
        ['飙升榜📈', 'up_list'],
